#!/bin/bash
# Validate every XML part of an IDML (.idml or unpacked dir) against Adobe's InDesign 2026 RelaxNG package schema (../schemas,
# generated by InDesign's app.generateIDMLSchema(), via metanorma/idml). The schema pins DOMVersion="21.5"; parts are copied
# with 21.0 -> 21.5 so the version string is the only thing rewritten. Needs: brew install jing-trang
set -o pipefail
D="$(cd "$(dirname "$0")" && pwd)"; S="$D/../schemas"
[ -f "$S/designmap.rnc" ] || bash "$D/fetch_schemas.sh" || exit 2
command -v jing >/dev/null || { echo "jing not found: brew install jing-trang"; exit 2; }
SRC="$1"; W=$(mktemp -d /tmp/idmlval.XXXXXX)
if [[ "$SRC" == *.idml ]]; then (cd "$W" && unzip -q "$SRC"); else cp -R "$SRC"/. "$W"/; fi
find "$W" -name '*.xml' -exec perl -pi -e 's/DOMVersion="21\.0"/DOMVersion="21.5"/g' {} +
rc=0
check() { local schema="$1"; shift; [ $# -eq 0 ] && return; [ -e "$1" ] || return
  out=$(JAVA_TOOL_OPTIONS="-Djdk.xml.elementAttributeLimit=0 -Djdk.xml.totalEntitySizeLimit=0" jing -c "$S/$schema" "$@" 2>&1); r=$?
  out=$(printf '%s\n' "$out" | grep -v 'Picked up JAVA_TOOL_OPTIONS')
  if [ "$r" -ne 0 ]; then rc=1; echo "FAIL $schema ($# files)"; echo "$out" | sed "s#$W/##" | head -${MAXLINES:-20}; else echo "ok   $schema ($# files)"; fi; }
check designmap.rnc "$W/designmap.xml"
for r in Graphic Fonts Styles Preferences; do check "Resources/$r.rnc" "$W/Resources/$r.xml"; done
shopt -s nullglob
check MasterSpreads/MasterSpread.rnc "$W"/MasterSpreads/*.xml
check Spreads/Spread.rnc "$W"/Spreads/*.xml
check Stories/Story.rnc "$W"/Stories/*.xml
check XML/BackingStory.rnc "$W/XML/BackingStory.xml"
check XML/Tags.rnc "$W/XML/Tags.xml"
rm -rf "$W"
exit $rc
